import mido
from collections import Counter, defaultdict, deque
import statistics

GM = ('Acoustic Grand Piano,Bright Acoustic Piano,Electric Grand Piano,Honky-tonk Piano,Electric Piano 1,Electric Piano 2,Harpsichord,Clavinet,Celesta,Glockenspiel,Music Box,Vibraphone,Marimba,Xylophone,Tubular Bells,Dulcimer,Drawbar Organ,Percussive Organ,Rock Organ,Church Organ,Reed Organ,Accordion,Harmonica,Tango Accordion,Acoustic Guitar nylon,Acoustic Guitar steel,Electric Guitar jazz,Electric Guitar clean,Electric Guitar muted,Overdriven Guitar,Distortion Guitar,Guitar harmonics,Acoustic Bass,Electric Bass finger,Electric Bass pick,Fretless Bass,Slap Bass 1,Slap Bass 2,Synth Bass 1,Synth Bass 2,Violin,Viola,Cello,Contrabass,Tremolo Strings,Pizzicato Strings,Orchestral Harp,Timpani,String Ensemble 1,String Ensemble 2,Synth Strings 1,Synth Strings 2,Choir Aahs,Voice Oohs,Synth Voice,Orchestra Hit,Trumpet,Trombone,Tuba,Muted Trumpet,French Horn,Brass Section,Synth Brass 1,Synth Brass 2,Soprano Sax,Alto Sax,Tenor Sax,Baritone Sax,Oboe,English Horn,Bassoon,Clarinet,Piccolo,Flute,Recorder,Pan Flute,Blown Bottle,Shakuhachi,Whistle,Ocarina,Lead square,Lead sawtooth,Lead calliope,Lead chiff,Lead charang,Lead voice,Lead fifths,Lead bass and lead,Pad new age,Pad warm,Pad polysynth,Pad choir,Pad bowed,Pad metallic,Pad halo,Pad sweep,FX rain,FX soundtrack,FX crystal,FX atmosphere,FX brightness,FX goblins,FX echoes,FX sci-fi,Sitar,Banjo,Shamisen,Koto,Kalimba,Bag pipe,Fiddle,Shanai,Tinkle Bell,Agogo,Steel Drums,Woodblock,Taiko Drum,Melodic Tom,Synth Drum,Reverse Cymbal,Guitar Fret Noise,Breath Noise,Seashore,Bird Tweet,Telephone Ring,Helicopter,Applause,Gunshot').split(',')
PC = ['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B']
DR = {35:'bass drum 2',36:'bass drum',37:'side stick',38:'snare',39:'hand clap',40:'electric snare',41:'low floor tom',42:'closed hi-hat',43:'high floor tom',44:'pedal hi-hat',45:'low tom',46:'open hi-hat',47:'low-mid tom',48:'high-mid tom',49:'crash cymbal',50:'high tom',51:'ride cymbal',52:'Chinese cymbal',53:'ride bell',54:'tambourine',55:'splash cymbal',56:'cowbell',57:'crash cymbal 2',59:'ride cymbal 2',60:'high bongo',61:'low bongo',62:'mute high conga',63:'open high conga',64:'low conga',75:'claves'}

def note(n):
    return PC[n % 12] + str(n // 12 - 1)

def adapt(path):
    try:
        mid = mido.MidiFile(path, clip=True)
    except Exception as e:
        return {'text': 'Could not parse MIDI file: ' + str(e)[:200]}
    ppq = mid.ticks_per_beat
    if ppq <= 0:
        return {'text': 'MIDI file with SMPTE timing; %d tracks, timing division %d.' % (len(mid.tracks), ppq)}
    events = []
    track_ends = []
    for ti, track in enumerate(mid.tracks):
        t = 0
        for order, msg in enumerate(track):
            t += msg.time
            events.append((t, ti, order, msg))
        track_ends.append(t)
    events.sort(key=lambda x: (x[0], x[1], x[2]))
    programs = [0] * 16
    active = defaultdict(deque)
    notes = defaultdict(list)
    tempos, meters, keys, metadata = [], [], [], []
    for t, ti, order, msg in events:
        typ = msg.type
        if typ == 'set_tempo': tempos.append((t, msg.tempo))
        elif typ == 'time_signature': meters.append((t, msg.numerator, msg.denominator))
        elif typ == 'key_signature': keys.append((t, msg.key))
        elif typ in ('track_name','instrument_name','lyrics','text','marker','copyright'):
            s = getattr(msg, 'text', getattr(msg, 'name', ''))
            if s and len(metadata) < 20: metadata.append('%s: %s' % (typ, str(s)[:100]))
        elif typ == 'program_change': programs[msg.channel] = msg.program
        elif typ == 'note_on' and msg.velocity > 0:
            active[(msg.channel, msg.note)].append((t, msg.velocity, programs[msg.channel], ti))
        elif typ == 'note_off' or (typ == 'note_on' and msg.velocity == 0):
            q = active[(msg.channel, msg.note)]
            if q:
                start, vel, prog, tr = q.popleft()
                notes[msg.channel].append((start, max(0, t-start), msg.note, vel, prog, tr))
    end = max(track_ends or [0])
    for (ch, pitch), q in active.items():
        while q:
            start, vel, prog, tr = q.popleft()
            notes[ch].append((start, max(0, end-start), pitch, vel, prog, tr))
    for ch in notes: notes[ch].sort()
    tempo_events = sorted(tempos) or [(0, 500000)]
    if tempo_events[0][0] > 0: tempo_events.insert(0, (0, 500000))
    seconds = 0.0
    for i, (t, tempo) in enumerate(tempo_events):
        nxt = tempo_events[i+1][0] if i+1 < len(tempo_events) else end
        seconds += max(0, min(end, nxt)-t) * tempo / (ppq * 1000000)
    lines = ['MIDI type %s, %d track(s), %d ticks per quarter; duration %.1f seconds, %.1f quarter-note beats; %d note events.' % (mid.type, len(mid.tracks), ppq, seconds, end/ppq, sum(map(len, notes.values())))]
    lines.append('Tempo: ' + ', '.join('%.1f BPM at beat %.1f' % (60000000/v, t/ppq) for t,v in tempo_events[:8]) + (' (more changes)' if len(tempo_events)>8 else ''))
    lines.append('Meter: ' + (', '.join('%d/%d at beat %.1f' % (a,b,t/ppq) for t,a,b in meters[:8]) if meters else 'not specified (MIDI default 4/4)'))
    if keys: lines.append('Key signature metadata: ' + ', '.join('%s at beat %.1f' % (k,t/ppq) for t,k in keys[:8]))
    if metadata: lines.append('Metadata: ' + '; '.join(metadata[:10]))
    allpit = Counter()
    for ch, ns in sorted(notes.items(), key=lambda x: -len(x[1]))[:12]:
        pitches = [n[2] for n in ns]
        velocities = [n[3] for n in ns]
        progs = Counter(n[4] for n in ns)
        starts = sorted(set(n[0] for n in ns))
        gaps = Counter(round((b-a)/ppq, 2) for a,b in zip(starts, starts[1:]) if b>a)
        durations = Counter(round(n[1]/ppq, 2) for n in ns if n[1]>0)
        simultaneous = Counter(n[0] for n in ns)
        if ch == 9:
            drums = Counter(pitches)
            desc = 'percussion: ' + ', '.join('%s %d' % (DR.get(p, 'MIDI drum %d' % p), c) for p,c in drums.most_common(10))
        else:
            allpit.update(p % 12 for p in pitches)
            desc = 'programs ' + ', '.join('%s (%d notes)' % (GM[p] if 0 <= p < 128 else str(p), c) for p,c in progs.most_common(4))
            desc += '; range %s-%s' % (note(min(pitches)), note(max(pitches)))
        lines.append('Channel %d: %s; %d notes, velocity median %d (range %d-%d); %d distinct onset times, max %d simultaneous notes.' % (ch+1, desc, len(ns), statistics.median(velocities), min(velocities), max(velocities), len(starts), max(simultaneous.values())))
        if gaps: lines.append('  Common onset spacings in quarter beats: ' + ', '.join('%g (%d)' % x for x in gaps.most_common(5)))
        if durations: lines.append('  Common note lengths in quarter beats: ' + ', '.join('%g (%d)' % x for x in durations.most_common(5)))
        if ch != 9:
            groups = defaultdict(list)
            for t,d,p,v,pr,tr in ns[:1000]: groups[t].append(p)
            seq = []
            for t in sorted(groups)[:24]:
                ps = sorted(groups[t])
                seq.append('%g:%s' % (round(t/ppq,2), '+'.join(note(p) for p in ps[:5])))
            lines.append('  Opening onsets (quarter beat:pitches): ' + ' '.join(seq))
    if allpit:
        lines.append('Pitch-class counts across pitched channels: ' + ', '.join('%s %d' % (PC[p],c) for p,c in allpit.most_common()))
        onset_groups = defaultdict(set)
        for ch, ns in notes.items():
            if ch != 9:
                for t,d,p,v,pr,tr in ns: onset_groups[t].add(p % 12)
        chords = Counter(tuple(sorted(s)) for s in onset_groups.values() if len(s)>=3)
        if chords:
            lines.append('Most common simultaneous onset pitch sets: ' + '; '.join('%s (%d)' % ('-'.join(PC[p] for p in chord), count) for chord,count in chords.most_common(8)))
    return {'text': '\n'.join(lines)[:4000]}
